drop policy if exists fleet_route_updates_read_authenticated on public.fleet_route_updates; create policy fleet_route_updates_scoped_read on public.fleet_route_updates for select to authenticated using (coalesce((select is_admin from public.profiles where id=auth.uid()),false) or exists(select 1 from public.fleet_routes r join public.app_business_memberships m on m.business_id=r.business_id where r.id=fleet_route_updates.route_id and m.user_id=auth.uid()) or exists(select 1 from public.fleet_routes r join public.fleet_drivers d on d.id=r.driver_id where r.id=fleet_route_updates.route_id and lower(coalesce(d.email,''))=lower(coalesce((select email from auth.users where id=auth.uid()),'')))); drop policy if exists enterprise_engagement_read_authenticated on public.enterprise_engagement_events; create policy enterprise_engagement_scoped_read on public.enterprise_engagement_events for select to authenticated using (coalesce((select is_admin from public.profiles where id=auth.uid()),false) or exists(select 1 from public.enterprise_partner_networks n join public.app_business_memberships m on m.business_id=n.owner_business_id where n.id=enterprise_engagement_events.network_id and m.user_id=auth.uid()) or exists(select 1 from public.enterprise_partner_network_members nm join public.enterprise_partner_networks n on n.id=nm.network_id join public.app_business_memberships m on m.business_id=nm.partner_business_id where nm.network_id=enterprise_engagement_events.network_id and nm.status='active' and m.user_id=auth.uid())); drop policy if exists enterprise_engagement_insert_authenticated on public.enterprise_engagement_events; create policy enterprise_engagement_scoped_insert on public.enterprise_engagement_events for insert to authenticated with check (coalesce((select is_admin from public.profiles where id=auth.uid()),false) or exists(select 1 from public.enterprise_partner_networks n join public.app_business_memberships m on m.business_id=n.owner_business_id where n.id=enterprise_engagement_events.network_id and m.user_id=auth.uid()));
